{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.12","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"nvidiaTeslaT4","dataSources":[{"sourceType":"competition","sourceId":128431,"databundleVersionId":15477148},{"sourceType":"datasetVersion","sourceId":15083066,"datasetId":9619129,"databundleVersionId":15966527},{"sourceType":"datasetVersion","sourceId":15083112,"datasetId":9656889,"databundleVersionId":15966578},{"sourceType":"modelInstanceVersion","sourceId":772747,"databundleVersionId":15913955,"modelInstanceId":590171,"modelId":602498},{"sourceType":"modelInstanceVersion","sourceId":790706,"databundleVersionId":16148332,"modelInstanceId":603462,"modelId":615599},{"sourceType":"modelInstanceVersion","sourceId":785125,"databundleVersionId":16062647,"modelInstanceId":599081,"modelId":611339}],"dockerImageVersionId":31286,"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":true}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-03-18T05:35:24.825588Z\",\"iopub.execute_input\":\"2026-03-18T05:35:24.826775Z\",\"iopub.status.idle\":\"2026-03-18T05:36:03.546649Z\",\"shell.execute_reply.started\":\"2026-03-18T05:35:24.826737Z\",\"shell.execute_reply\":\"2026-03-18T05:36:03.545055Z\"}}\nimport os\nimport glob\nimport random\nimport warnings\nimport multiprocessing\nimport pandas as pd\nimport numpy as np\nimport librosa\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nimport pytorch_lightning as pl\nimport torchaudio.transforms as T\nfrom torch.utils.data import Dataset, DataLoader\nfrom pytorch_lightning.callbacks import EarlyStopping, ModelCheckpoint, StochasticWeightAveraging\nfrom pytorch_lightning.loggers import WandbLogger\nfrom torchmetrics.classification import MulticlassF1Score\nfrom transformers import ASTModel, get_cosine_schedule_with_warmup\nfrom pathlib import Path\nfrom tqdm import tqdm\nimport concurrent.futures\n\nos.system('uv pip install --upgrade wandb')\nimport wandb\n\n# ==========================================\n# 0. CONFIGURATION & SETUP\n# ==========================================\nwarnings.filterwarnings('ignore')\npl.seed_everything(14, workers=True)\n\nRUN_GENERATION = False\nRUN_TRAINING = False\nRUN_INFERENCE = True\n\nCONFIG = {\n    \"project_name\": \"23f2001635-t12026\",\n    \"experiment_name\": \"ast_mashup_v6_megaset\",\n    \"data_root\": \"/kaggle/input/competitions/jan-2026-dl-gen-ai-project/messy_mashup\",\n    \n    # ⚠️ THE MEGASET: Point to ALL your generated datasets ⚠️\n    \"synthetic_data_dir\": \"/kaggle/input/datasets/harshitsahu01/dataset-for-ast-v1/processed_data_ast\",\n    \"pseudo_labeled_dataset\": \"/kaggle/input/datasets/harshitsahu01/messymashup-pseudolabeled-audios/pseudo_labels\", \n    \"pure_mashups_dir\": \"/kaggle/working/pure_mashups\", # Assuming you generated these in the last run\n    \n    \"best_checkpoint\": \"/kaggle/input/models/harshitsahu01/ast-mashup-v6-megaset/pytorch/v6_megaset/1/best-ast-v5.ckpt\",\n    \"save_dir\": \"/kaggle/working/pure_mashups\", \n    \n    \"head_lr\": 1e-4,         \n    \"backbone_lr\": 2e-5,     \n    \"weight_decay\": 0.05,\n    \"label_smoothing\": 0.05, \n    \n    \"batch_size\": 24,\n    \"accumulate_grad\": 4,    \n    \"num_epochs\": 40,\n    \"patience\": 8, \n    \"num_classes\": 10,\n    \"sample_rate\": 16000,\n    \"ast_frames\": 1024,\n    \"duration\": 30,\n    \"num_workers\": multiprocessing.cpu_count()\n}\n\nGENRES = [\"blues\", \"classical\", \"country\", \"disco\", \"hiphop\", \n          \"jazz\", \"metal\", \"pop\", \"reggae\", \"rock\"]\nGENRE_TO_IDX = {g: i for i, g in enumerate(GENRES)}\nIDX_TO_GENRE = {i: g for i, g in enumerate(GENRES)}\n\nAST_MEAN = -4.2677393\nAST_STD = 4.5689974\n\nif RUN_TRAINING:\n    from kaggle_secrets import UserSecretsClient\n    try:\n        user_secrets = UserSecretsClient()\n        wandb.login(key=user_secrets.get_secret(\"WANDB_API_KEY\"))\n    except Exception as e:\n        print(f\"WandB login skipped/failed: {e}\")\n\n# ==========================================\n# 1. PURE MASHUP GENERATOR (Bulletproof Version)\n# ==========================================\n\n# Cache the noise files globally so we don't spam Kaggle's disk I/O 1000 times\ndef get_all_noise_files(data_root):\n    noise_dir = Path(data_root) / \"ESC-50-master\" / \"audio\"\n    files = glob.glob(str(noise_dir / \"*.wav\"))\n    if not files:\n        print(f\"🚨 WARNING: No noise files found in {noise_dir}! Check your path.\")\n    return files\n\ndef process_true_song(song_folder, genre, config, noise_files):\n    try:\n        data_root, sr = config[\"data_root\"], config[\"sample_rate\"]\n        target_samples = config[\"duration\"] * sr\n        \n        # 1. Reconstruct True Song\n        stems = []\n        for stem_type in [\"drums\", \"bass\", \"vocals\", \"other\"]:\n            stem_path = Path(song_folder) / f\"{stem_type}.wav\"\n            if stem_path.exists():\n                audio, _ = librosa.load(stem_path, sr=sr)\n                if len(audio) > target_samples: audio = audio[:target_samples]\n                else: audio = np.pad(audio, (0, target_samples - len(audio)))\n                stems.append(audio)\n            else:\n                print(f\"⚠️ Missing stem: {stem_path}\")\n        \n        if not stems: \n            print(f\"❌ Failed: No valid stems found in {song_folder}\")\n            return False\n            \n        mixed_audio = np.sum(stems, axis=0)\n\n        # 2. Inject ESC-50 Noise\n        if noise_files:\n            noise_audio, _ = librosa.load(random.choice(noise_files), sr=sr)\n            if len(noise_audio) < len(mixed_audio):\n                noise_audio = np.tile(noise_audio, int(np.ceil(len(mixed_audio) / len(noise_audio))))\n            noise_audio = noise_audio[:len(mixed_audio)]\n            \n            target_snr = random.uniform(5, 15)\n            rms_sig = np.sqrt(np.mean(mixed_audio**2)+1e-6)\n            rms_noise = np.sqrt(np.mean(noise_audio**2)+1e-6)\n            mixed_audio += noise_audio * (rms_sig / rms_noise) * (10 ** (-target_snr / 20))\n\n        # 3. Create AST-Compliant Spectrogram\n        mel_spec = librosa.feature.melspectrogram(\n            y=mixed_audio, sr=sr, n_mels=128, n_fft=400, hop_length=160\n        )\n        mel_spec_db = librosa.power_to_db(mel_spec, ref=np.max)\n        mel_spec_db = (mel_spec_db - AST_MEAN) / (AST_STD * 2)\n        tensor = torch.tensor(mel_spec_db, dtype=torch.float32) \n        \n        # 4. Slice into 3 deterministic chunks\n        total_frames = tensor.shape[1]\n        frames = config[\"ast_frames\"]\n        \n        if total_frames > frames:\n            crop1 = tensor[:, 0 : frames]\n            crop2 = tensor[:, (total_frames - frames) // 2 : ((total_frames - frames) // 2) + frames]\n            crop3 = tensor[:, total_frames - frames : total_frames]\n            crops = [crop1, crop2, crop3]\n        else:\n            crops = [F.pad(tensor, (0, frames - total_frames))] * 3\n\n        # 90-10 Split\n        prefix = \"train\" if random.random() < 0.9 else \"val\"\n        save_dir = Path(config[\"save_dir\"]) / prefix / genre\n        save_dir.mkdir(parents=True, exist_ok=True)\n        \n        song_name = Path(song_folder).name\n        for i, crop in enumerate(crops):\n            torch.save(crop, save_dir / f\"{song_name}_part{i}.pt\")\n            \n        return True\n        \n    except Exception as e:\n        # NO MORE SILENT FAILURES. Print exactly what crashed.\n        print(f\"\\n❌ CRASH in {song_folder}: {str(e)}\")\n        return False\n\ndef generate_pure_data():\n    print(\"--- GENERATING 3000 TRUE MASHUP CHUNKS ---\")\n    genre_dir = Path(CONFIG[\"data_root\"]) / \"genres_stems\"\n    noise_files = get_all_noise_files(CONFIG[\"data_root\"])\n    \n    tasks = []\n    for genre in GENRES:\n        genre_path = genre_dir / genre\n        if not genre_path.exists():\n            print(f\"🚨 WARNING: Genre path does not exist: {genre_path}\")\n            continue\n            \n        song_folders = [f.path for f in os.scandir(genre_path) if f.is_dir()]\n        for folder in song_folders:\n            tasks.append((folder, genre, CONFIG, noise_files))\n\n    success = 0\n    # Dropped workers slightly to prevent Kaggle CPU memory crashes\n    safe_workers = max(1, CONFIG['num_workers'] // 2) \n    \n    with concurrent.futures.ProcessPoolExecutor(max_workers=safe_workers) as executor:\n        futures = [executor.submit(process_true_song, *task) for task in tasks]\n        for future in tqdm(concurrent.futures.as_completed(futures), total=len(tasks)):\n            if future.result(): success += 3 \n            \n    print(f\"✅ Generated {success} high-fidelity AST tensors.\")\n\n# ==========================================\n# 2. RESTORED AUGMENTATION DATASET\n# ==========================================\nclass ASTPureDataset(Dataset):\n    def __init__(self, data_dir, config, is_train=True):\n        self.files = glob.glob(f\"{data_dir}/*/*.pt\")\n        self.target_frames = config[\"ast_frames\"]\n        self.is_train = is_train\n        \n        # Restored Augmentations to prevent overfitting on the small 3k dataset\n        self.time_masking = T.TimeMasking(time_mask_param=100)\n        self.freq_masking = T.FrequencyMasking(freq_mask_param=24)\n\n    def __len__(self): return len(self.files)\n\n    def __getitem__(self, idx):\n        file_path = self.files[idx]\n        label = GENRE_TO_IDX[Path(file_path).parent.name]\n        mel_spec = torch.load(file_path).to(torch.float32)\n        \n        mel_spec = mel_spec.transpose(0, 1)\n\n        # Apply SpecAugment ONLY during training\n        if self.is_train:\n            mel_spec = mel_spec.transpose(0, 1).unsqueeze(0)\n            mel_spec = self.time_masking(mel_spec)\n            mel_spec = self.freq_masking(mel_spec)\n            mel_spec = mel_spec.squeeze(0).transpose(0, 1)\n\n        return mel_spec, torch.tensor(label, dtype=torch.long)\n\n\n# ==========================================\n# 1. MEGASET DATASET LOADER\n# ==========================================\nclass ASTMegasetDataset(Dataset):\n    def __init__(self, data_dirs, config, is_train=True):\n        self.files = []\n        for d in data_dirs:\n            if os.path.exists(d):\n                self.files.extend(glob.glob(f\"{d}/*/*.pt\"))\n            \n        self.is_train = is_train\n        self.target_frames = config[\"ast_frames\"]\n        \n        # Lighter masking to prevent underfitting\n        self.time_masking = T.TimeMasking(time_mask_param=50)\n        self.freq_masking = T.FrequencyMasking(freq_mask_param=12)\n\n    def __len__(self): return len(self.files)\n\n    def __getitem__(self, idx):\n        file_path = self.files[idx]\n        label = GENRE_TO_IDX[Path(file_path).parent.name]\n        mel_spec = torch.load(file_path).to(torch.float32)\n        \n        total_frames = mel_spec.shape[1]\n        if total_frames > self.target_frames:\n            if self.is_train:\n                start = random.randint(0, total_frames - self.target_frames)\n            else:\n                start = (total_frames - self.target_frames) // 2\n            mel_spec = mel_spec[:, start : start + self.target_frames]\n        else:\n            mel_spec = F.pad(mel_spec, (0, self.target_frames - total_frames))\n\n        mel_spec = mel_spec.transpose(0, 1)\n\n        if self.is_train:\n            mel_spec = mel_spec.transpose(0, 1).unsqueeze(0)\n            mel_spec = self.time_masking(mel_spec)\n            mel_spec = self.freq_masking(mel_spec)\n            mel_spec = mel_spec.squeeze(0).transpose(0, 1)\n\n        return mel_spec, torch.tensor(label, dtype=torch.long)\n\n# ==========================================\n# 2. V5 ARCHITECTURE\n# ==========================================\nclass MessyMashupAST_v5(pl.LightningModule):\n    def __init__(self, config):\n        super().__init__()\n        self.save_hyperparameters(config)\n        self.config = config\n        \n        self.ast = ASTModel.from_pretrained(\"MIT/ast-finetuned-audioset-10-10-0.4593\")\n        self.classifier = nn.Sequential(\n            nn.Linear(768, 256),\n            nn.BatchNorm1d(256),\n            nn.ReLU(),\n            nn.Dropout(0.3), # Lock dropout at 0.3\n            nn.Linear(256, config[\"num_classes\"])\n        )\n\n        self.criterion = nn.CrossEntropyLoss(label_smoothing=config[\"label_smoothing\"])\n        self.train_f1 = MulticlassF1Score(num_classes=config[\"num_classes\"], average='macro')\n        self.val_f1 = MulticlassF1Score(num_classes=config[\"num_classes\"], average='macro')\n\n    def load_best_weights(self, checkpoint_path):\n        print(f\"Loading weights from: {checkpoint_path}\")\n        checkpoint = torch.load(checkpoint_path, map_location=lambda storage, loc: storage, weights_only=False)\n        state_dict = checkpoint['state_dict'] if 'state_dict' in checkpoint else checkpoint\n        \n        # Handle layer shape mismatches if transferring from focal loss architecture\n        model_dict = self.state_dict()\n        pretrained_dict = {k: v for k, v in state_dict.items() if k in model_dict and v.shape == model_dict[k].shape}\n        model_dict.update(pretrained_dict)\n        self.load_state_dict(model_dict)\n        self.classifier[3].p = 0.3 \n        print(\"✅ Successfully loaded weights.\")\n\n    def forward(self, x):\n        outputs = self.ast(x)\n        return self.classifier(outputs.last_hidden_state[:, 0, :])\n\n    def training_step(self, batch, batch_idx):\n        x, y = batch\n        \n        # NERFED MIXUP: Only 20% chance to mix, gentler alpha\n        if np.random.rand() < 0.2:\n            alpha = 0.2\n            lam = np.random.beta(alpha, alpha)\n            rand_index = torch.randperm(x.size()[0], device=x.device)\n            target_a, target_b = y, y[rand_index]\n            x = lam * x + (1 - lam) * x[rand_index]\n            logits = self(x)\n            loss = lam * self.criterion(logits, target_a) + (1 - lam) * self.criterion(logits, target_b)\n        else:\n            logits = self(x)\n            loss = self.criterion(logits, y)\n\n        preds = torch.argmax(logits, dim=1)\n        self.train_f1(preds, y)\n        self.log('train_loss', loss, prog_bar=True)\n        self.log('train_macro_f1', self.train_f1, on_epoch=True, prog_bar=True)\n        return loss\n\n    def validation_step(self, batch, batch_idx):\n        x, y = batch\n        logits = self(x)\n        preds = torch.argmax(logits, dim=1)\n        self.val_f1(preds, y)\n        self.log('val_loss', self.criterion(logits, y), prog_bar=True)\n        self.log('val_macro_f1', self.val_f1, prog_bar=True)\n\n    def configure_optimizers(self):\n        optimizer = torch.optim.AdamW([\n            {'params': self.ast.parameters(), 'lr': self.config[\"backbone_lr\"]},\n            {'params': self.classifier.parameters(), 'lr': self.config[\"head_lr\"]}\n        ], weight_decay=self.config[\"weight_decay\"])\n        \n        total_steps = self.trainer.estimated_stepping_batches\n        scheduler = get_cosine_schedule_with_warmup(\n            optimizer, num_warmup_steps=int(total_steps * 0.1), num_training_steps=total_steps\n        )\n        return {\"optimizer\": optimizer, \"lr_scheduler\": {\"scheduler\": scheduler, \"interval\": \"step\"}}\n\n# ==========================================\n# 3. INFERENCE ENGINE (Outputs Logits for Ensembling)\n# ==========================================\ndef run_inference_tta(model, config):\n    print(\"--- RUNNING INFERENCE WITH TTA ---\")\n    device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n    model = model.to(device)\n    model.eval()\n    \n    test_df = pd.read_csv(f\"{config['data_root']}/test.csv\")\n    predictions = []\n    \n    for _, row in tqdm(test_df.iterrows(), total=len(test_df)):\n        file_id = str(row['filename'])\n        if not file_id.endswith('.wav'):\n            file_id += '.wav'\n            \n        # Let's dynamically check where Kaggle actually put these files\n        path_options = [\n            os.path.join(config['data_root'], \"mashups\", file_id),\n            os.path.join(config['data_root'], \"test\", file_id),\n            os.path.join(config['data_root'], file_id)\n        ]\n        \n        audio_path = None\n        for path in path_options:\n            if os.path.exists(path):\n                audio_path = path\n                break\n                \n        if audio_path is None:\n            # If it can't find it anywhere, force it to use the first option so it crashes loudly\n            audio_path = path_options[0] \n        \n        try:\n            y, _ = librosa.load(audio_path, sr=config[\"sample_rate\"])\n            mel_spec = librosa.feature.melspectrogram(y=y, sr=config[\"sample_rate\"], n_mels=128, n_fft=400, hop_length=160)\n            mel_spec_db = (librosa.power_to_db(mel_spec, ref=np.max) - AST_MEAN) / (AST_STD * 2)\n            tensor = torch.tensor(mel_spec_db, dtype=torch.float32)\n            \n            total_frames = tensor.shape[1]\n            frames = config[\"ast_frames\"]\n            \n            if total_frames > frames:\n                crop1 = tensor[:, 0 : frames]\n                crop2 = tensor[:, (total_frames - frames) // 2 : ((total_frames - frames) // 2) + frames]\n                crop3 = tensor[:, total_frames - frames : total_frames]\n                batch = torch.stack([crop1.transpose(0, 1), crop2.transpose(0, 1), crop3.transpose(0, 1)]).to(device)\n            else:\n                crop = F.pad(tensor, (0, frames - total_frames))\n                batch = crop.transpose(0, 1).unsqueeze(0).to(device)\n\n            with torch.no_grad():\n                logits = model(batch)\n                avg_probs = torch.mean(F.softmax(logits, dim=1), dim=0)\n                pred_idx = torch.argmax(avg_probs).item()\n                predictions.append(IDX_TO_GENRE[pred_idx])\n                \n        except Exception as e:\n            # NO MORE SILENT FAILURES! \n            print(f\"\\n❌ FATAL ERROR on {audio_path}: {e}\")\n            predictions.append(\"pop\") \n\n    test_df['genre'] = predictions\n    test_df[['id', 'genre']].to_csv('submission.csv', index=False)\n    print(\"Saved predictions to submission.csv\")\n\n# ==========================================\n# 4. EXECUTION PIPELINE\n# ==========================================\nif __name__ == \"__main__\":\n\n    if RUN_GENERATION:\n        generate_pure_data()\n\n    if RUN_TRAINING:\n        print(\"--- STARTING V5 MEGASET TRAINING ---\")\n        \n        # Combine ALL data for training\n        train_dirs = [\n            f\"{CONFIG['synthetic_data_dir']}/train\", \n            f\"{CONFIG['pseudo_labeled_dataset']}/train\",\n            f\"{CONFIG['pure_mashups_dir']}/train\"\n        ]\n        \n        # Validate only on pure mashups and synthetic validation data\n        val_dirs = [\n            f\"{CONFIG['synthetic_data_dir']}/val\",\n            f\"{CONFIG['pure_mashups_dir']}/val\"\n        ]\n        \n        train_ds = ASTMegasetDataset(train_dirs, CONFIG, is_train=True)\n        val_ds = ASTMegasetDataset(val_dirs, CONFIG, is_train=False)\n        \n        train_loader = DataLoader(train_ds, batch_size=CONFIG[\"batch_size\"], shuffle=True, num_workers=0)\n        val_loader = DataLoader(val_ds, batch_size=CONFIG[\"batch_size\"], shuffle=False, num_workers=0)\n        \n        print(f\"Total Megaset Training Chunks: {len(train_ds)}\")\n        print(f\"Total Validation Chunks: {len(val_ds)}\")\n        \n        model = MessyMashupAST_v5(CONFIG)\n        if os.path.exists(CONFIG[\"best_checkpoint\"]):\n            model.load_best_weights(CONFIG[\"best_checkpoint\"])\n        \n        checkpoint_cb = ModelCheckpoint(\n            dirpath=\"checkpoints_v5\", filename=\"best-ast-v5\", monitor=\"val_macro_f1\", mode=\"max\", save_top_k=1\n        )\n        early_stop_cb = EarlyStopping(monitor=\"val_macro_f1\", patience=CONFIG[\"patience\"], mode=\"max\", verbose=True)\n        swa_cb = StochasticWeightAveraging(swa_lrs=1e-5)\n        wandb_logger = WandbLogger(project=CONFIG[\"project_name\"], name=CONFIG[\"experiment_name\"])\n        \n        trainer = pl.Trainer(\n            max_epochs=CONFIG[\"num_epochs\"],\n            accelerator=\"gpu\",\n            devices=1,\n            logger=wandb_logger,\n            callbacks=[checkpoint_cb, early_stop_cb, swa_cb],\n            accumulate_grad_batches=CONFIG[\"accumulate_grad\"],\n            gradient_clip_val=1.0, \n            precision=\"16-mixed\",\n            deterministic=True\n        )\n        \n        trainer.fit(model, train_loader, val_loader)\n        \n    if RUN_INFERENCE:\n        dataset_ckpt = CONFIG[\"best_checkpoint\"]\n        \n        if os.path.exists(dataset_ckpt):\n            print(f\"🚀 Loading 12-hour trained checkpoint: {dataset_ckpt}\")\n            # 1. Initialize the blank architecture\n            model = MessyMashupAST_v5(CONFIG)\n            # 2. Load the weights using your custom function\n            model.load_best_weights(dataset_ckpt)\n            # 3. Ensure inference mode\n            model.eval()\n        else:\n            print(f\"🚨 CRITICAL ERROR: Could not find your checkpoint at {dataset_ckpt}\")\n            print(\"Check the path! The model will guess randomly without it.\")\n            model = MessyMashupAST_v5(CONFIG)\n            \n        run_inference_tta(model, CONFIG)\n\n# %% [code]\n","metadata":{"_uuid":"ccb3d505-b77a-4282-9016-911cd8ae1bb7","_cell_guid":"93c952b6-6643-4c41-9585-872184374567","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}